import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a sword → base premium 100 G");
    it.todo("an amulet → base premium 60 G");
    it.todo("a staff → base premium 80 G");
    it.todo("a potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-scoped modifiers", () => {
    it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
    it.todo("sword with enchantment 5 → 30 % high-enchantment surcharge applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo(
      "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (of the sword only) → 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-scoped modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
    it.todo("second quote in the scenario → 15 % follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G (first insurance surcharge still applies)",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause only)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause only)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)",
    );
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than the policy covers → error");
  });

  describe("errors", () => {
    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
    it.todo("claim references a damage entry whose item is not part of the policy → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a JSON scenario from stdin and writes { results } to stdout");
    it.todo("quote result contains premium; claim result contains payout and remainingCap");
    it.todo("on error, exits with a non-zero status code and writes a description to stderr, with no results on stdout");
  });
});

