export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const premiumFor = (step: QuoteStep): number => {
  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map((step) => ({ premium: premiumFor(step as QuoteStep) })) };
};

