export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type KnownItemType = keyof typeof BASE_PREMIUMS;

const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const countsByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
};

const basePremiumForGroup = (itemType: string, count: number): number => {
  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
  return count * basePremiumOf(itemType);
};

const policyBasePremiumOf = (items: Item[]): number =>
  [...countsByType(items)].reduce(
    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
    0,
  );

const premiumFor = (quote: QuoteStep): number => {
  const policyBase = policyBasePremiumOf(quote.items);
  return Math.ceil(policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
};

const resultOf = (step: Step): StepResult => {
  if (step.op === "quote") return { premium: premiumFor(step) };
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(resultOf),
});

