        op: "claim",
        policy: 0,
        incident: { cause: "fire", damages: [{ itemType: "sword", amount: 901 }] },
      },
    ],
  });

  // 901 × 0.5 = 450.5, − 100 = 350.5 → rounded down in the MHPCO's favour.
